for (size_t i = start; i < end; i++) {
    Particle& particle = particles[i];

    // Update position based on velocity
    particle.position += particle.velocity * deltaTime;

    // Apply gravity
    particle.velocity.y -= g * deltaTime;

    // Boundary conditions - box with elasticity
    if (particle.position.x < -boxWidth) {
        particle.position.x = -boxWidth;
        particle.velocity.x *= -elasticity;
    } else if (particle.position.x > boxWidth) {
        particle.position.x = boxWidth;
        particle.velocity.x *= -elasticity;
    }

    if (particle.position.y < -boxWidth) {
        particle.position.y = -boxWidth;
        particle.velocity.y *= -elasticity;
    } else if (particle.position.y > boxWidth) {
        particle.position.y = boxWidth;
        particle.velocity.y *= -elasticity;
    }

    if (particle.position.z < -boxWidth) {
        particle.position.z = -boxWidth;
        particle.velocity.z *= -elasticity;
    } else if (particle.position.z > boxWidth) {
        particle.position.z = boxWidth;
        particle.velocity.z *= -elasticity;
    }

    // Update transform matrix
    particleTransforms[i] = glm::translate(particle.position) * settings.sphereScale;
}

